WITH supplier_totals AS (SELECT supplier_id, MAX(price) - MIN(price) AS price_range, SUM(CASE WHEN brand = 'Acme' THEN price ELSE 0 END) AS acme_price FROM products WHERE ARRAY_CONTAINS(tags, 'sale') GROUP BY supplier_id) SELECT s.id, s.supplier_name, s.country, st.price_range, st.acme_price FROM suppliers s INNER JOIN supplier_totals st ON s.id = st.supplier_id ORDER BY s.id DESC;
